function emergencyTransfer(address recipient) external onlyOwner {
    uint256 phUSDBalance = phUSD.balanceOf(address(this));
    uint256 rewardTokenBalance = rewardToken.balanceOf(address(this));
    if (phUSDBalance > 0)        IERC20(address(phUSD)).safeTransfer(recipient, phUSDBalance);
    if (rewardTokenBalance > 0)  rewardToken.safeTransfer(recipient, rewardTokenBalance);
    _pause();
}
